def check_solution(k1, C=2051323):
    a1 = k1**2 - C
    if a1 <= 0:
        return None, "a1 not positive"
    k3_fourth = a1**3 + C

    # Check if k3_fourth is a perfect fourth power
    k3_check_lower = int(k3_fourth**(0.25))
    k3_check_upper = k3_check_lower + 1

    for k3 in range(k3_check_lower, k3_check_upper + 1):
        if k3**4 == k3_fourth:
            return k3, a1

    return None, None

k1_values = [1434, 1435, 1436]
results = {}

for k1 in k1_values:
    k3, a1 = check_solution(k1)
    if k3 is not None:
        results[k1] = (k3, a1)
    else:
        results[k1] = "No solution found"

print(results)

